#include <stdio.h>

void insertion_sort(int fish[], int n) {
    for (int i = 1; i < n; i++) {
        int hold = fish[i];
        int j = i - 1;
        while (j >= 0 && fish[j] > hold) {
            fish[j + 1] = fish[j];
            j--;
        }
        fish[j + 1] = hold;
    }
}

int main(void) {
    int fish[5] = {5, 1, 4, 2, 8};
    insertion_sort(fish, 5);
    printf("理牌式：");
    for (int i = 0; i < 5; i++) {
        printf("%d ", fish[i]);
    }
    printf("\n");
    return 0;
}
